<script setup>
import {computed,ref} from 'vue'
import Icon from './Icon.vue'
import HelpTip from './HelpTip.vue'
import {keywords} from './discoveryRanking'
import {regions} from './regions'
import InstituteMembership from './InstituteMembership.vue'
import {call,uploadImage} from './service'
import {educationPresets,nextProviderCode,validateProvider} from './marketplace'
const props=defineProps({data:Object,member:Object})
const emit=defineEmits(['refresh','notify','discover'])
const owned=computed(()=>props.data.providers.filter(p=>p.owner===props.member.name))
const step=ref(0),editing=ref(null),error=ref(''),busy=ref(false),saved=ref(null)
const fresh=()=>({type:'Institute',title:'',username:'',country:'Sri Lanka',currency:'LKR',timezone:'Asia/Colombo',city:'',education_system:educationPresets['Sri Lanka'][0],languages:'Sinhala, English',subjects:'',bio:'',qualifications:'',experience:0,teaching_style:'',availability:'',website:'',youtube_url:'',video_visibility:'Public',socials:{youtube:'',facebook:'',instagram:'',linkedin:'',tiktok:'',twitter:''},color:'#e6def9',profile_image:'',cover_image:''})
const form=ref(fresh()),keywordText=ref('')
const systems=computed(()=>educationPresets[form.value.country]||educationPresets.Other)
const generatedCode=computed(()=>editing.value?form.value.code:nextProviderCode(form.value.title||'Education Workspace',props.data.providers))
function newWorkspace(){keywordText.value='';form.value=fresh();editing.value=null;step.value=0;saved.value=null;error.value=''}
function edit(p){keywordText.value=(p.keywords||[]).join(', ');form.value={...fresh(),...p,socials:{...fresh().socials,...p.socials}};editing.value=p.name;step.value=1;saved.value=null;error.value=''}
function changeCountry(){form.value.education_system=systems.value[0];const region=regions[form.value.country];if(region){form.value.currency=region.currency;form.value.timezone=region.timezone;form.value.languages=region.languages}}
function next(){error.value='';if(step.value===1){if(!form.value.title.trim()||!/^[a-z][a-z0-9]{2,29}$/.test(form.value.username)){error.value='Add your display name and a username of 3–30 lowercase letters and numbers, starting with a letter.';return}if(props.data.providers.some(p=>p.username===form.value.username&&p.name!==editing.value)){error.value='That username is already in use. Choose another.';return}}step.value++}
async function upload(e,field){try{form.value[field]=await uploadImage(e.target.files[0])}catch(e){error.value=e.message}}
async function save(){error.value='';busy.value=true;try{form.value.keywords=keywords(keywordText.value,form.value.type==='Institute'?15:5);validateProvider(form.value,props.data.providers,editing.value);const result=await call('save_provider',{data:{...form.value,name:editing.value}});saved.value=result;emit('refresh');emit('notify','Public demo profile saved in this browser. No live workspace or login was provisioned.')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">A SPACE FOR EVERY WAY OF TEACHING</div><h1>{{editing?'Make your profile your own.':'Bring your learning community to Sisu.'}}</h1><p>Choose your role, education system and public identity.</p></div><button class="button subtle" @click="$emit('discover')">Explore the directory <Icon name="ArrowRight" :size="16"/></button></div><InstituteMembership :key="member.name" :member="member" @notify="$emit('notify',$event)"/><div v-if="owned.length&&!saved" class="owned-profiles"><span>Manage your demo profiles</span><button v-for="p in owned" class="button subtle small" @click="edit(p)">{{p.title}} <Icon name="Pencil" :size="14"/></button></div>
<section v-if="saved" class="panel setup-success"><span class="stat-icon mint"><Icon name="CircleCheck" :size="32"/></span><span class="eyebrow">YOUR DEMO PROFILE IS READY</span><h2>{{saved.title}}</h2><p>Your public username and workspace code have different jobs.</p><div class="identity-preview"><span><small>Public username</small><strong>@{{saved.username}}</strong></span><span><small>{{saved.type==='Institute'?'Institute':'Teacher workspace'}} code</small><strong>{{saved.code}}</strong></span></div><p>Student ID example: <b>ST-{{saved.code}}-00001</b><br>Teacher ID example: <b>TC-{{saved.code}}-0001</b></p><div class="inline wrap"><button class="button primary" @click="$emit('discover')">View the directory <Icon name="ArrowRight" :size="16"/></button><button class="button subtle" @click="edit(saved)">Edit profile</button></div><p class="field-help">Preview only. Production onboarding must verify ownership, provision the isolated workspace and create authenticated accounts on the server.</p></section>
<section v-else class="setup-layout"><aside class="setup-sidebar"><span class="brand-symbol">s</span><h2>Your teaching.<br>Your identity.<br>Your community.</h2><ol><li v-for="(label,i) in ['Choose your workspace','Your education & identity','Build your public profile']" :class="{active:step===i,complete:step>i}"><span>{{i+1}}</span>{{label}}</li></ol><p>Already teaching somewhere? Your public profile can help students discover you while private class records stay in the right workspace.</p></aside><div class="panel setup-form"><div class="section-heading"><span class="eyebrow">STEP {{step+1}} OF 3</span><span class="badge violet">Demo onboarding</span></div><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="step===0"><h2>How will you teach?</h2><p>Pick the workspace that fits your work. Your public profile will reflect this choice.</p><div class="workspace-types"><button v-for="choice in [{name:'Institute',icon:'Building2',body:'Manage an academy, school, college or training centre with multiple teachers.'},{name:'Independent teacher',icon:'GraduationCap',body:'Build your personal teaching brand, publish classes and welcome your own students.'}]" :class="{chosen:form.type===choice.name}" :aria-pressed="form.type===choice.name" @click="form.type=choice.name"><Icon :name="choice.icon" :size="28"/><strong>{{choice.name}}</strong><p>{{choice.body}}</p><Icon v-if="form.type===choice.name" name="CircleCheck" :size="18"/></button></div></template>
<template v-if="step===1"><h2>Your name. Your education system.</h2><label>{{form.type==='Institute'?'Institute display name':'Teacher full name'}}<input v-model="form.title" maxlength="100" placeholder="Teen Academy Sri Lanka" required></label><label>Public username <HelpTip text="Your searchable public handle, such as teenacademysl. It is separate from your institute code and from your secure sign-in credentials."/><input v-model="form.username" maxlength="30" placeholder="teenacademysl" autocomplete="off" required></label><div class="identity-preview"><span><small>Public profile</small><strong>@{{form.username||'yourusername'}}</strong></span><span><small>Generated workspace code</small><strong>{{generatedCode}}</strong></span></div><div class="form-row"><label>Country<select v-model="form.country" @change="changeCountry"><option v-if="!Object.keys(educationPresets).includes(form.country)">{{form.country}}</option><option v-for="c in Object.keys(educationPresets)">{{c}}</option></select></label><label>City / region<input v-model="form.city" maxlength="80" placeholder="Colombo"></label></div><label v-if="form.country==='Other'">Country name<input v-model="form.custom_country" maxlength="80" required placeholder="Enter your country"></label><label>Education system<select v-model="form.education_system"><option v-if="!systems.includes(form.education_system)&&form.education_system!=='Custom education system'">{{form.education_system}}</option><option v-for="system in systems">{{system}}</option><option v-if="!systems.includes('Custom education system')">Custom education system</option></select></label><label v-if="form.education_system==='Custom education system'">Education system name<input v-model="form.custom_system" maxlength="120" placeholder="Name your curriculum or programme"></label><div class="form-row"><label>Billing currency <HelpTip text="Sets the provider’s display currency. The current payments.lk adapter collects LKR only. Other currencies require a compatible regional gateway before real checkout."/><select v-model="form.currency"><option v-for="c in [...new Set(Object.values(regions).map(r=>r.currency))]">{{c}}</option></select></label><label>Teaching time zone<select v-model="form.timezone"><option v-for="zone in [...new Set([...Object.values(regions).map(r=>r.timezone),'UTC','America/Los_Angeles','Asia/Beirut'])]">{{zone}}</option></select></label></div><label>Teaching languages<input v-model="form.languages" maxlength="150" placeholder="English, Sinhala, Tamil"></label></template>
<template v-if="step===2"><h2>Let students get to know you.</h2><div class="form-row"><label>Profile image / logo<input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,'profile_image')"><img v-if="form.profile_image" :src="form.profile_image" class="upload-preview" alt="Profile preview"></label><label>Cover image<input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,'cover_image')"><img v-if="form.cover_image" :src="form.cover_image" class="upload-preview" alt="Cover preview"></label></div><label>About {{form.type==='Institute'?'your institute':'you'}} · {{form.bio.length}} / 1000<textarea v-model="form.bio" maxlength="1000" placeholder="Your teaching story, approach and what learners can expect."></textarea></label><label>Discovery keywords · up to {{form.type==='Institute'?15:5}}<HelpTip text="Add clear subjects and teaching specialisms, separated by commas. Keywords help match learner interests; repeating keywords does not improve your ranking."/><textarea v-model="keywordText" maxlength="800" placeholder="Mathematics, A/L, Sinhala"></textarea></label><label>Subjects / specialisms<input v-model="form.subjects" maxlength="200" placeholder="Mathematics, Physics, Academic English"></label><template v-if="form.type==='Independent teacher'"><div class="form-row"><label>Qualifications<input v-model="form.qualifications" maxlength="200" placeholder="Your qualifications and awarding institution"></label><label>Years of teaching<input v-model.number="form.experience" type="number" min="0" max="80"></label></div><label>Teaching approach<input v-model="form.teaching_style" maxlength="240" placeholder="Worked examples, live practice and individual feedback"></label><label>Availability & time zone<input v-model="form.availability" maxlength="200" placeholder="Saturday 16:00–18:00 · Asia/Colombo"></label></template><h3>Introduce yourself on video</h3><label>YouTube teaser video URL <HelpTip label="YouTube teaser visibility help" text="Use a public or unlisted YouTube URL with embedding enabled for your public teaser. Private videos require an invited Google account; LMS enrollment cannot unlock them. This field does not change YouTube privacy settings."/><input v-model="form.youtube_url" type="url" placeholder="https://youtu.be/YSul9yrAvN4"></label><label>Video visibility on YouTube<select v-model="form.video_visibility"><option>Public</option><option>Unlisted</option><option>Private</option></select></label><p v-if="form.video_visibility==='Private'" class="form-note">Private videos cannot serve as a generally accessible teaser. Students may see a YouTube restriction until invited by the video owner.</p><h3>Connect your social presence</h3><p class="field-help">These are public profile links, not OAuth account connections. No posting permissions or account passwords are requested.</p><label v-for="(title,key) in {youtube:'YouTube channel',facebook:'Facebook',instagram:'Instagram',linkedin:'LinkedIn',tiktok:'TikTok',twitter:'X / Twitter'}" :key="key">{{title}}<input v-model="form.socials[key]" type="url" placeholder="https://…"></label><label>Website<input v-model="form.website" type="url" placeholder="https://…"></label></template>
<div class="setup-actions"><button class="button subtle" :disabled="step===0" @click="step--;error=''">Back</button><button v-if="step<2" class="button primary" @click="next">Continue <Icon name="ArrowRight" :size="16"/></button><button v-else class="button primary" :disabled="busy" @click="save">{{busy?'Saving…':editing?'Save public profile':'Create demo workspace'}} <Icon name="ArrowRight" :size="16"/></button></div></div></section></template>
